#include <stdio.h>
#include <stdlib.h>

long catalan(int n) {
    if (n == 0 || n == 1) {
        return 1;
    }

    long catalan_n = 0;
    for (int i = 0; i < n; i++) {
        catalan_n += catalan(i) * catalan(n - i - 1);
    }

    return catalan_n;
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        printf("NO_INPUT\n");
        return 1;
    }

    char *endptr;
    long n = strtol(argv[1], &endptr, 10);

    if (endptr == argv[1]) {
        printf("BAD_INPUT\n");
        return 1;
    }

    if (n < 0) {
        printf("OUT_OF_RANGE\n");
        return 1;
    }

    long result = catalan(n);
    printf("%lld\n", result);

    return 0;
}
